shell_commands:
cat << 'EOF' > patch.js
const fs = require('fs');
const content = fs.readFileSync('src/orchestration/chatOrchestrator.test.ts', 'utf8');

const newTest = `  it('sums usage from every provider call in a multi-round turn', async () => {
    let seenUsage: UsageMetadata | undefined;
    const hooks: OrchestratorHooks = {
      afterModelResponse: async (_session, _text, totalUsage) => {
        seenUsage = totalUsage;
      },
    };
    const orchestrator = createChatOrchestrator(
      scriptedProvider([
        [TOOL_CALL, {type: 'stop', stopReason: 'tool_use', usage: {inputTokens: 10, outputTokens: 2, totalTokens: 12}}],
        [TOOL_CALL, {type: 'stop', stopReason: 'tool_use', usage: {inputTokens: 15, outputTokens: 3, totalTokens: 18}}],
        [{type: 'text', text: 'done'}, {type: 'stop', stopReason: 'end_turn', usage: {inputTokens: 20, outputTokens: 5, totalTokens: 25}}],
      ]),
      promptBuilder,
      registryReturning({result: 'r'}),
      {hooks}
    );

    await orchestrator.processMessage(createSession('ask'));

    expect(seenUsage).toEqual({inputTokens: 45, outputTokens: 10, totalTokens: 55});
  });

`;

const insertPoint = content.indexOf(`  it('keeps the usage an earlier round reported when a later round reports none'`);
const patched = content.substring(0, insertPoint) + newTest + content.substring(insertPoint);

fs.writeFileSync('src/orchestration/chatOrchestrator.test.ts', patched);
EOF
node patch.js
